// Decode des FC3-Registerblocks (Adr. 0..8) des SunSpec-Simulators in die
// Messwerte für vp-telemetrie. Skalierung: edge/sim/sunspec-sim.js.
const r = msg.payload;
if (!Array.isArray(r) || r.length < 9) { return null; }
const s16 = (v) => (v > 32767 ? v - 65536 : v);
const grid_kw = s16(r[0]) / 100;   // + Bezug / - Einspeisung
const pv_kw = s16(r[1]) / 100;
const load_kw = s16(r[2]) / 100;
const soc_pct = r[4] / 10;
const wmax_lim_pct = r[5] / 100;   // beobachtete §14a-Begrenzung in %
const grid_conn_kw = r[6] / 100;
const grid_limit_kw = Math.round((wmax_lim_pct / 100) * grid_conn_kw * 1000) / 1000;
const reading = {
  ts: new Date().toISOString(),
  power_kw: grid_kw,
  soc_pct,
  pv_power_kw: pv_kw,
  load_kw,
  grid_limit_kw,
};
node.status({ fill: 'green', shape: 'dot', text: 'pv ' + pv_kw.toFixed(1) + ' kW, SoC ' + soc_pct.toFixed(0) + ' %' });
return [{ payload: reading }, { payload: true }];

// Der Sollwert ist bereits durch die Guards des Core begrenzt; hier nur die
// Übersetzung ins Register (int16, 0,01 kW, Zweierkomplement).
const kw = Number(msg.payload);
if (!isFinite(kw)) { return null; }
const raw = Math.round(kw * 100) & 0xffff;
msg.payload = { value: raw, fc: 6, unitid: 1, address: 40, quantity: 1 };
node.status({ fill: 'blue', shape: 'dot', text: (msg.setpoint && msg.setpoint.source || '?') + ' -> ' + kw.toFixed(1) + ' kW' });
return msg;

// PRO KUNDE ANPASSEN: Registerbelegung + Skalierung des konkreten
// Wechselrichters. Ausgang 1: Messwerte für vp-telemetrie; Ausgang 2: true
// als Link-Lebenszeichen.
const r = msg.payload;
if (!Array.isArray(r) || r.length < 9) { return null; }
const s16 = (v) => (v > 32767 ? v - 65536 : v);
const reading = {
  ts: new Date().toISOString(),
  power_kw: s16(r[0]) / 100,
  soc_pct: r[4] / 10,
  pv_power_kw: s16(r[1]) / 100,
  load_kw: s16(r[2]) / 100,
  grid_limit_kw: Math.round(((r[5] / 100) / 100) * (r[6] / 100) * 1000) / 1000,
};
return [{ payload: reading }, { payload: true }];

// PRO KUNDE ANPASSEN: Zielregister/Encoding des Wechselrichters.
const kw = Number(msg.payload);
if (!isFinite(kw)) { return null; }
const raw = Math.round(kw * 100) & 0xffff;
msg.payload = { value: raw, fc: 6, unitid: 1, address: 40, quantity: 1 };
return msg;

// Deye-Konfiguration - PRO KUNDE ANPASSEN (VoltPilot-Service, nicht der Kunde).
// Mehrere Wechselrichter: das Array erweitern; die Lese-Kette liest Index 0,
// fuer weitere Geraete diesen Tab duplizieren.
// family: 'string' | 'hybrid_1p' | 'hybrid_3p' | 'micro'.
// Vorzeichen (Netz/Batterie) ERST AM GERAET kalibrieren - siehe DEYE.md.
flow.set('deye_wechselrichter', [
  {
    id: 'wr1',
    ip: '192.168.1.50',
    port: 48899,
    family: 'hybrid_1p',
    invert_grid_sign: false,
    invert_batt_sign: false,
    // Nur string/micro: erlaubte Stufen der Wirkleistungsbegrenzung in %
    // (leer = 1-%-Schritte), z. B. [0, 25, 50, 75, 100].
    limit_stages: []
  }
]);
node.status({ fill: 'grey', shape: 'dot', text: 'Konfiguration geladen' });
return null;

// Baut den Leseplan (Modbus-Bloecke) fuer den konfigurierten Wechselrichter und
// stoesst die erste Leseanfrage an. Ausgabe: msg.payload = deye-Argumente
// (String, wird vom exec-Knoten an "deye" angehaengt), msg.deye = Laufkontext.
// Registerkarten/Skalierung: edge-app/nodered/deye/deye-decode.js (getestet).
const READS = {
  string:    [{ start: 0x0050, count: 0x007d }],
  hybrid_1p: [{ start: 0x00a9, count: 0x0016 }],
  hybrid_3p: [{ start: 0x024c, count: 0x0056 }],
  micro:     []
};
const list = flow.get('deye_wechselrichter') || [];
const cfg = list[0];
if (!cfg) { node.status({ fill: 'red', shape: 'ring', text: 'keine Konfiguration' }); return null; }
const reads = READS[cfg.family] || [];
if (reads.length === 0) {
  node.status({ fill: 'grey', shape: 'ring', text: cfg.family + ': keine Messwert-Register' });
  return null;
}
const target = cfg.ip + ':' + (cfg.port || 48899);
const h4 = (n) => (n & 0xffff).toString(16).padStart(4, '0').toUpperCase();
msg.deye = { cfg, target, reads, i: 0, blocks: [] };
const r = reads[0];
msg.payload = ['-t', target, '-xmb', h4(r.start) + h4(r.count)].join(' ');
return msg;

// Parst die +ok=0103-Antwort des aktuellen Blocks (stdout des exec-Knotens),
// haengt die Register an msg.deye.blocks und liest den naechsten Block - oder
// gibt an den Decoder ab (Ausgang 2). Sequenziell, damit nie zwei deye-Prozesse
// gleichzeitig auf den Logger zugreifen.
const ctx = msg.deye;
if (!ctx) return null;
const parseOk = (stdout) => {
  if (typeof stdout !== 'string') return null;
  const m = stdout.match(/\+ok=0103([0-9a-fA-F]{2})([0-9a-fA-F]+)/);
  if (!m) return null;
  const byteCount = parseInt(m[1], 16);
  const hex = m[2];
  if (!byteCount || hex.length < byteCount * 2) return null;
  const dataHex = hex.slice(0, byteCount * 2);
  const regs = [];
  for (let j = 0; j * 4 < dataHex.length; j++) regs.push(parseInt(dataHex.substr(j * 4, 4), 16));
  return regs;
};
const regs = parseOk(msg.payload);
const cur = ctx.reads[ctx.i];
if (regs) ctx.blocks.push({ start: cur.start, regs });
else node.status({ fill: 'yellow', shape: 'ring', text: 'Block ' + ctx.i + ' ohne Antwort' });
ctx.i += 1;
if (ctx.i < ctx.reads.length) {
  const h4 = (n) => (n & 0xffff).toString(16).padStart(4, '0').toUpperCase();
  const r = ctx.reads[ctx.i];
  msg.payload = ['-t', ctx.target, '-xmb', h4(r.start) + h4(r.count)].join(' ');
  return [msg, null]; // naechster Block -> zurueck an exec
}
return [null, msg]; // alle Bloecke gelesen -> Decoder

// Decodiert die gelesenen Register in die flache edge/telemetry-Nachricht.
// Nur die kanonischen Cloud-Felder gehen an vp-telemetrie; die Batterieleistung
// (batt_kw) ist reine Kalibrierhilfe (Status/Debug) - die Cloud leitet sie aus
// der Leistungsbilanz ab. Quelle der Wahrheit + Tests:
// edge-app/nodered/deye/deye-decode.js
const ctx = msg.deye;
if (!ctx || !ctx.blocks.length) { node.status({ fill: 'red', shape: 'ring', text: 'keine Register' }); return null; }
const cfg = ctx.cfg;
const FAMILIES = {
  string: { hasBattery: false, fields: {
    pv:   { addr: 0x0050, bits: 32, signed: false, scale: 0.1 },
    load: { addr: 0x00c6, bits: 32, signed: false, scale: 1 },
    grid: { addr: 0x00cb, bits: 32, signed: true,  scale: 1 } } },
  hybrid_1p: { hasBattery: true, fields: {
    grid: { addr: 0x00a9, bits: 16, signed: true,  scale: 1 },
    load: { addr: 0x00b2, bits: 16, signed: false, scale: 1 },
    soc:  { addr: 0x00b8, bits: 16, signed: false, scale: 1, kind: 'pct' },
    pv:   { addrs: [0x00ba, 0x00bb], bits: 16, signed: false, scale: 1, sum: true },
    batt: { addr: 0x00be, bits: 16, signed: true,  scale: 1 } } },
  hybrid_3p: { hasBattery: true, fields: {
    soc:  { addr: 0x024c, bits: 16, signed: false, scale: 1, kind: 'pct' },
    batt: { addr: 0x024e, bits: 16, signed: true,  scale: 1 },
    grid: { addr: 0x0271, bits: 16, signed: true,  scale: 1 },
    load: { addr: 0x028d, bits: 16, signed: false, scale: 1 },
    pv:   { addrs: [0x02a0, 0x02a1], bits: 16, signed: false, scale: 1, sum: true } } },
  micro: { hasBattery: false, fields: {} }
};
const fam = FAMILIES[cfg.family];
if (!fam) { node.status({ fill: 'red', shape: 'ring', text: 'unbekannte Familie' }); return null; }
const s16 = (v) => { v &= 0xffff; return v > 0x7fff ? v - 0x10000 : v; };
const r3 = (x) => Math.round(x * 1000) / 1000;
const r1 = (x) => Math.round(x * 10) / 10;
const readReg = (addr) => {
  for (const b of ctx.blocks) { const o = addr - b.start; if (o >= 0 && o < b.regs.length) return b.regs[o]; }
  return undefined;
};
const fieldValue = (f) => {
  let raw;
  if (f.bits === 32) {
    const lo = readReg(f.addr), hi = readReg(f.addr + 1);
    if (lo === undefined || hi === undefined) return undefined;
    raw = hi * 65536 + lo; if (f.signed && raw > 0x7fffffff) raw -= 0x100000000;
  } else if (f.sum) {
    raw = 0; for (const a of f.addrs) { const v = readReg(a); if (v === undefined) return undefined; raw += f.signed ? s16(v) : (v & 0xffff); }
  } else {
    const v = readReg(f.addr); if (v === undefined) return undefined; raw = f.signed ? s16(v) : (v & 0xffff);
  }
  return raw * (f.scale === undefined ? 1 : f.scale);
};
const toKw = (w) => r3(w / 1000);
const f = fam.fields;
const reading = { ts: new Date().toISOString() };
if (f.pv)   { const w = fieldValue(f.pv);   if (w !== undefined) reading.pv_power_kw = toKw(w); }
if (f.load) { const w = fieldValue(f.load); if (w !== undefined) reading.load_kw = toKw(w); }
if (f.grid) { let w = fieldValue(f.grid);   if (w !== undefined) { if (cfg.invert_grid_sign) w = -w; reading.power_kw = toKw(w); } }
if (fam.hasBattery && f.soc)  { const s = fieldValue(f.soc);  if (s !== undefined) reading.soc_pct = r1(s); }
let batt_kw;
if (fam.hasBattery && f.batt) { let w = fieldValue(f.batt);   if (w !== undefined) { if (cfg.invert_batt_sign) w = -w; batt_kw = toKw(w); } }
const keys = Object.keys(reading).filter((k) => k !== 'ts');
if (keys.length === 0) { node.status({ fill: 'yellow', shape: 'ring', text: 'keine Messwerte decodiert' }); return null; }
const pv = reading.pv_power_kw !== undefined ? reading.pv_power_kw.toFixed(1) : '?';
const soc = reading.soc_pct !== undefined ? (', SoC ' + reading.soc_pct.toFixed(0) + ' %') : '';
const bt = batt_kw !== undefined ? (', Batt ' + batt_kw.toFixed(1) + ' kW') : '';
node.status({ fill: 'green', shape: 'dot', text: 'pv ' + pv + ' kW' + soc + bt });
return [{ payload: reading }, { payload: true }];

// Familien-Autoerkennung: sondiert die SoC-Register beider Hybrid-Karten
// (low 0x00B8 vs. high 0x024C). Genau eine liefert einen sinnvollen 0..100-Wert
// -> Hybrid-Familie erkannt. String/micro haben keinen SoC und werden manuell
// gewaehlt. Ergebnis erscheint im Debug-Fenster + Knotenstatus.
const list = flow.get('deye_wechselrichter') || [];
const cfg = list[0];
if (!cfg) { node.status({ fill: 'red', shape: 'ring', text: 'keine Konfiguration' }); return null; }
const target = cfg.ip + ':' + (cfg.port || 48899);
msg.detect = { target, step: 0, low: null, high: null };
msg.payload = ['-t', target, '-xmb', '00B80001'].join(' '); // low-map SoC
node.status({ fill: 'blue', shape: 'dot', text: 'sondiere low map (0x00B8)...' });
return msg;

// Wertet die SoC-Sonden aus. Schritt 0: low-map-Antwort merken, high-map anfragen.
// Schritt 1: high-map-Antwort merken, Familie bestimmen.
const d = msg.detect;
if (!d) return null;
const probeSoc = (stdout) => {
  if (typeof stdout !== 'string') return null;
  const m = stdout.match(/\+ok=0103([0-9a-fA-F]{2})([0-9a-fA-F]+)/);
  if (!m) return null; const bc = parseInt(m[1], 16); const hex = m[2];
  if (!bc || hex.length < bc * 2) return null;
  return parseInt(hex.substr(0, 4), 16);
};
const soc = probeSoc(msg.payload);
if (d.step === 0) {
  d.low = soc; d.step = 1;
  msg.payload = ['-t', d.target, '-xmb', '024C0001'].join(' '); // high-map SoC
  node.status({ fill: 'blue', shape: 'dot', text: 'sondiere high map (0x024C)...' });
  return [msg, null];
}
d.high = soc;
const sane = (v) => typeof v === 'number' && v >= 0 && v <= 100;
const lowOk = sane(d.low), highOk = sane(d.high);
let family = null;
if (lowOk && !highOk) family = 'hybrid_1p';
else if (highOk && !lowOk) family = 'hybrid_3p';
const txt = family
  ? ('Familie erkannt: ' + family + ' (low=' + d.low + ', high=' + d.high + ')')
  : ('unklar - low=' + d.low + ', high=' + d.high + ' (string/micro manuell)');
node.status({ fill: family ? 'green' : 'yellow', shape: family ? 'dot' : 'ring', text: txt });
msg.payload = { family, low_soc: d.low, high_soc: d.high };
return [null, msg];

// Wirkleistungsbegrenzung fuer string/micro -> Register 0x0028 (0..100 %).
// Eingang: msg.payload = gewuenschte Begrenzung in Prozent.
// DIES ist die klar benannte Steuerstelle: hier bildet VoltPilot seine
// Kurve / §14a-Vorgabe auf die vom Geraet akzeptierten Stufen ab
// (cfg.limit_stages). Batteriesteuerung fuer Hybride ist BEWUSST NICHT hier -
// siehe den Abschnitt "Ausgeklammert" in DEYE.md.
const list = flow.get('deye_wechselrichter') || [];
const cfg = list[0];
if (!cfg) { node.status({ fill: 'red', shape: 'ring', text: 'keine Konfiguration' }); return null; }
if (!(cfg.family === 'string' || cfg.family === 'micro')) {
  node.status({ fill: 'yellow', shape: 'ring', text: cfg.family + ': kein 0x0028-Schreibpfad' });
  return null;
}
const target = cfg.ip + ':' + (cfg.port || 48899);
let p = Math.round(Number(msg.payload));
if (!isFinite(p)) p = 100;
p = Math.max(0, Math.min(100, p));
const stages = Array.isArray(cfg.limit_stages) ? cfg.limit_stages : [];
if (stages.length) p = stages.reduce((b, s) => (Math.abs(s - p) < Math.abs(b - p) ? s : b), stages[0]);
const h4 = (n) => (n & 0xffff).toString(16).padStart(4, '0').toUpperCase();
msg.payload = ['-t', target, '-xmbw', '00280001' + '02' + h4(p)].join(' ');
node.status({ fill: 'blue', shape: 'dot', text: 'Begrenzung -> ' + p + ' %' });
return msg;
